# 第 2 批：卦 9-17（小畜、履、泰、否、同人、大有、谦、豫、随）

HEXAGRAMS = {
  "9": {
    "zh": "小畜卦下乾上巽，以小力量畜住大力量。它讲的是积蓄的道理——乌云密布却还没下雨，说明积得不够，得再等时机。",
    "en": "Xiaochu is strength below, compliance above — a small force holding a large one. It's about accumulating: dense clouds but no rain yet means you haven't stored enough. Wait for the time.",
    "ja": "小畜は下が乾、上が巽。小さい力で大きい力を畜える。蓄えることを表す——雲は厚いのに雨が降らない。まだ積もりが足りない。時を待つこと。",
  },
  "10": {
    "zh": "履卦下兑上乾，喜悦而应和。它讲的是守礼有分寸——像踩着老虎尾巴走路，心里戒惧又不失礼，才能顺通行事。",
    "en": "Lü is joy below, strength above — gladness responding. It's about walking with propriety and measure — like treading on a tiger's tail: stay alert without losing decorum, and you get through.",
    "ja": "履は下が兑、上が乾。悦んで応じる。礼を守り度をわきまえることを表す——虎の尾を踏むような歩み。戒めつつ礼を失わなければ、通じる。",
  },
  "11": {
    "zh": "泰卦下乾上坤，天地相交、通泰。它讲的是上下沟通、心意相同的好局面；但泰到了极点就会转否，所以要存一份防满的心。",
    "en": "Tai is heaven and earth intersecting — strength below, yielding above. It's the good situation of upper and lower connecting, hearts in agreement. But when Tai peaks it turns to Pi, so keep a watch against complacency.",
    "ja": "泰は下が乾、上が坤。天地が交わる。上下が通じ、志が同じという良い状況を表す。しかし泰も極まれば否に転じる。満ちることを警戒する心を保つこと。",
  },
  "12": {
    "zh": "否卦下坤上乾，天地不交、闭塞。它讲的是闭塞不通的道理——否到了极点就会转泰；在闭塞的时候，要收敛德行、避开祸难，不可妄动。",
    "en": "Pi is heaven and earth not intersecting — yield below, strength above. It's about blockage: when Pi peaks it turns to Tai. In a blocked time, draw in your virtue and avoid danger — don't act rashly.",
    "ja": "否は下が坤、上が乾。天地が交わらない。行き詰まりを表す——否も極まれば泰に転じる。塞がった時は徳を控えめにし、難を避ける。むやみに動いてはならない。",
  },
  "13": {
    "zh": "同人卦下离上乾，与人合同。它讲的是同中要有别——在旷野中与人和同是公，只跟同宗的人抱团是私；公私之别，看的是你跟谁同、为什么同。",
    "en": "Tongren is clarity below, strength above — uniting with others. It's about unity with distinctions: uniting in the open field is public spirit; uniting only with your own clan is private. The line between public and private lies in whom you join and why.",
    "ja": "同人は下が離、上が乾。人と同じ志を結ぶ。同じの中に違いがあることを表す——野で結べば公、身内だけで結べば私。公私の別は、誰と・なぜ結ぶかにかかっている。",
  },
  "14": {
    "zh": "大有卦下乾上离，光明盛大。它讲的是盛大时要知止——拥有很多的时候，要靠谦逊克制来保住所有。",
    "en": "Dayou is strength below, clarity above — brightness and abundance. It's about knowing when to stop in a time of plenty: when you have much, preserve it through modesty and restraint.",
    "ja": "大有は下が乾、上が離。明るく盛ん。盛んな時に知って止めることを表す——多くを持つ時は、謙虚で控えめな姿勢でその富を守る。",
  },
  "15": {
    "zh": "谦卦下艮上坤，谦而又谦。它讲的是谦的美德——谦逊的人反而受人尊重、越发高大，谦到极处也无人能越过它。这是六十四卦里唯一六爻都好的卦。",
    "en": "Qian is mountain below, earth above — humility upon humility. It's the virtue of modesty: the humble person is honored and grows taller; at the depth of humility no one can surpass them. This is the only one of the 64 hexagrams where all six lines are good.",
    "ja": "謙は下が艮、上が坤。謙でまた謙。謙の徳を表す——謙虚な者はかえって尊ばれ、いっそう高くなる。謙の極に至れば誰も越えられない。六十四卦で唯一、六爻すべてが良い卦である。",
  },
  "16": {
    "zh": "豫卦下坤上震，顺而动。它讲的是预备的道理——豫是预先准备，不是贪图安逸享乐。",
    "en": "Yu is yielding below, movement above — acting in accord. It's about preparation: Yu means getting ready beforehand, not indulging in ease and pleasure.",
    "ja": "豫は下が坤、上が震。従って動く。備えの道理を表す——豫とは前もって準備することで、安逸や享楽にふけることではない。",
  },
  "17": {
    "zh": "随卦下震上兑，动而随从。它讲的是随时势而变的道理——顺着时势走，但不随波逐流；跟着谁、随什么，贵在正当。",
    "en": "Sui is movement below, joy above — acting and following. It's about adapting to the times: follow the current of the times but don't drift with it. Whom and what you follow must be right.",
    "ja": "随は下が震、上が兑。動いて従う。時勢に順応する道理を表す——時の流れに従うが、流されない。誰に・何に従うかは、正しさが肝心。",
  },
}

LINES = {
  # 9 小畜
  "9-0": {"zh": "你在最底下，知道自己是被上面的阴畜住的，就自己回到正道上。懂得适可而止、迷途知返，不跟着别人跑而丢了自己的操守——回到根本，小过失就累不成了。", "en": "You're at the bottom; knowing you're being held by the yin above, you return to the path yourself. Knowing when to stop and turning back, not following others and losing your principles — return to the root and small faults won't pile up.", "ja": "一番下にいて、上の陰に畜えられていると知り、みずから道へ戻る。止まることを知り、迷って返る——人に従って操守を失わない。本に返れば、小さな過ちも積もらない。"},
  "9-1": {"zh": "你在下卦正中，和初九同类相互牵引，一起回到正道。志同道合的人相互提携、一起回头，不是只顾自己好——大家的正气互相扶持，回来的力量就大。", "en": "You're at the center of the lower trigram, drawn together with the first line, returning to the path as one. Like-minded people pull each other back, not just saving themselves — mutual support makes the return strong.", "ja": "下卦の中央で、初九と同じ類として引き合い、共に道へ戻る。志を同じくする者が互いに導き合い、共に返る——自分だけ良ければよいのではない。正气が支え合えば、戻る力は強い。"},
  "9-2": {"zh": "你在下卦最上面，过于刚强又不居中，被四爻畜住，心里不安。刚强却没个准，就管不住自己；内部不和，就失了相互畜止的道理。", "en": "You're at the top of the lower trigram — too rigid, off-center, held by the fourth line, restless. Rigid without balance, you can't manage yourself; discord within loses the very principle of mutual restraint.", "ja": "下卦の最上部にいて、剛すぎて中を外れ、四爻に畜えられて心が落ち着かない。剛で分别を欠けば自分を保てない。内が調わなければ、互いに畜め合う道を失う。"},
  "9-3": {"zh": "你在上卦下面，用柔畜住刚，诚意积在心里，上下就相互信任。用真诚打交道，疑惧就消了——柔能胜刚，靠的是诚信，不是蛮力。", "en": "You're below the upper trigram, holding rigidity with softness; sincerity stored inside makes upper and lower trust each other. Meet others with genuine feeling and fear and suspicion fade — softness overcomes hardness through faith, not force.", "ja": "上卦の下にいて、柔で剛を畜え、誠意を内に積めば上下が信じ合う。誠をもって接すれば疑いや恐れは消える——柔が剛に勝つのは力ではなく、誠があるからだ。"},
  "9-4": {"zh": "你身居尊位，是畜卦的主爻，用诚信把上下的阳爻团结起来。团结众人的关键在信义牢固——与其自己独享富足，不如跟大家共享。", "en": "You're in the place of honor, the main line, binding the yang lines above and below with sincerity. The key to uniting people is solid trust — rather than hoarding abundance alone, share it with others.", "ja": "尊い位にいて、畜の主爻となり、誠信で上下の陽を結びつける。衆をまとめる要は信義が固いこと。一人で富を独占するより、人と分かち合うほうがよい。"},
  "9-5": {"zh": "你到了卦的顶，畜道已成，阴德积满，像月亮将要圆。积到极处就会通，德积够了才能承载万物；但满了还不止，往前走就失了正。", "en": "You're at the top of the hexagram; the work of accumulation is done, yin virtue full, like the moon nearing full. At the extreme it opens up; virtue accumulated can carry things. But if you keep going when full, you lose your way.", "ja": "卦の頂点にいて、畜める道は成り、陰の徳は満ち、月が満ちんとするばかり。極まれば通じ、徳が積もって初めて物を載せられる。しかし満ちてまだ止めなければ、進んで正を失う。"},
  # 10 履
  "10-0": {"zh": "你在最底下，是履卦的开始，按自己本分做事，不加掩饰。守住本分，不因外物改变操守——初心没被染，走出去就不离正道。", "en": "You're at the bottom, the start of Lü — walking in your own station, without embellishment. Keep your place, don't let outside things change your principles — with an unstained beginning, you won't stray from the path.", "ja": "一番下で、履の初め。自分の分をわきまえて行い、飾りをつけない。分を守り、外物で操守を変えない。初心が汚れていなければ、出て行っても道を外れない。"},
  "10-1": {"zh": "你在下卦正中，履之道平坦，上面没有应援也不求显达。路本来就平坦，怕的是自己非要出风头——独来独往不求人知，这叫幽人的操守。", "en": "You're at the center of the lower trigram; the path of Lü is level, with no support above and no seeking of prominence. The road is naturally flat; the trouble is craving to be seen. Walking alone without needing others to know — that's the integrity of the recluse.", "ja": "下卦の中央で、履く道は平ら。上に応えもせず、自ら目立とうとしない。道はもともと平坦で、患いは自分で顕れを求めること。独行して人に知られることを求めない——これを幽人の貞という。"},
  "10-2": {"zh": "你在下卦上面，不中不正，眼光和行为都偏了还硬要去做。本事撑不起事情却硬撑，等于自己往险里跳——量力而行，才是保身之道。", "en": "You're at the top of the lower trigram — off-center and improper, your view and conduct skewed, yet you force ahead. Ability can't carry the task but you push anyway — that's leaping into danger yourself. Knowing your measure before acting is how you stay safe.", "ja": "下卦の上部にいて、中も正も外れ、見方も行いも偏っているのに無理に事をする。才が任に足りないのに無理に任うのは、自ら険に飛び込むこと。力量を見計らって動くのが、身を守る道だ。"},
  "10-3": {"zh": "你在上卦下面，靠近九五的刚，用柔顺和戒惧行事。靠近刚强却不放肆，小心警惕地走——能把戒惧常放心上，即使走在险处也不受伤。", "en": "You're below the upper trigram, near the rigidity of the fifth line, acting with softness and fear. Near strength but not reckless, moving with caution — if you keep fear in your heart, even on dangerous ground you won't be hurt.", "ja": "上卦の下にいて、九五の剛に近く、柔と恐れをもって行く。剛に近くても勝手にふるまわず、戒めて慎重に歩む——恐れを心に保てれば、険を履んでも傷つかない。"},
  "10-4": {"zh": "你身居尊位，果断去履行，以刚行刚、毫无顾虑。刚过头又没有制约，即使做得对也危险——决断的关键在于仔细审度，不在于一味果敢。", "en": "You're in the place of honor, acting decisively, meeting rigidity with rigidity, without a second thought. Rigidity overdone and unchecked is dangerous even when right — the key to decision is careful weighing, not raw boldness.", "ja": "尊い位にいて、決して履み、剛をもって剛を行い、何ら顧みない。剛が過ぎて制するものがなければ、正しくても危うい。決する要は詳しく審えることで、断ち切ることではない。"},
  "10-5": {"zh": "你到了卦的顶，履之道已成，回头看自己走过的路，检验得失。走到底再回望开头，看看哪里对哪里错——周旋没有亏欠，这就是学问到家的地方。", "en": "You're at the top of the hexagram; the path of Lü is complete. Look back over what you've done and examine your gains and losses. Having reached the end, review the beginning — if nothing is lacking in your conduct, that's learning brought to completion.", "ja": "卦の頂点にいて、履く道は成った。自分の歩みを振り返り、得失を確かめる。終わりに至って初めを省みる——行いに欠けがなければ、それが学びの成就するところだ。"},
  # 11 泰
  "11-0": {"zh": "你在最底下，和上面两个阳爻同类相引、一起上进，这是泰的开始。志同道合的人相互引进，不是只顾自己——同类一起起来，正道才行得通。", "en": "You're at the bottom, drawn up together with the two yang lines above — the start of Tai. Like-minded people bring each other forward, not just saving themselves — when the whole group rises, the way can be walked.", "ja": "一番下にいて、上の二つの陽と同じ類として引き合い、共に進む。泰の初めだ。志を同じくする者が互いに進め、自分だけ良ければよいのではない。同じ類が共に起これば、道は行われる。"},
  "11-1": {"zh": "你在下卦正中，上应六五，能包容下面的人而不陷于私。处在泰的兴盛时，贵在能容——容得下粗疏，用得了果敢，却不偏袒自己亲近的人。", "en": "You're at the center of the lower trigram, matched with the sixth line above, able to embrace those below without sinking into favoritism. In the height of Tai, what counts is tolerance — accept the rough, use the bold, but don't tilt toward your own.", "ja": "下卦の中央にいて、六五に応じ、下の者を包みながら私に溺れない。泰の盛んな時、貴ぶべきは包容だ——荒いところも容れ、果敢さも用い、親しい者に偏らない。"},
  "11-2": {"zh": "你在下卦最上面，正当泰的中段，平地将要转成斜坡。平的一定会倾斜，去的一定会回来，这是天地的常规——懂这个而不仗着盛势自满，才能守住长久。", "en": "You're at the top of the lower trigram, at the middle of Tai, where level ground is about to slope. What's level must tilt; what goes must return — that's the way of heaven and earth. Knowing this and not relying on prosperity keeps you steady.", "ja": "下卦の最上部にいて、泰の真ん中、平らな地が坂に変わろうとしている。平らなものは必ず傾き、行ったものは必ず返る——天地の常だ。これを知って盛りを恃まなければ、恒久に守れる。"},
  "11-3": {"zh": "你在上卦下面，三个阴爻相跟着往下走，不用告诫就自己来了。同类相从，不用约定就相互信任——势头已经形成，不是靠力气能拦住的。", "en": "You're below the upper trigram; three yin lines follow each other downward, coming on their own without warning. Like follows like, trusting without promise — the tide has formed and can't be stopped by force.", "ja": "上卦の下にいて、三つの陰が連なって下へ向かい、戒められずとも自ら来る。同じ類は約さずとも信じ合う——勢いはすでに成っており、力では止められない。"},
  "11-4": {"zh": "你身居尊位，柔和中正而向下呼应九二，以尊贵的身份降低姿态。处高位却能礼贤下士，把身份地位忘了去追随贤者——这是泰的最高境界。", "en": "You're in the place of honor, soft and centered, reaching down to the second line — high status lowering itself. In high position you humble yourself before the worthy, forgetting rank to follow them — that's the height of Tai.", "ja": "尊い位にいて、柔らかく中を得て下の九二に応じ、貴い身で頭を下げる。高位にいながら人を敬い、位を忘れて賢者に従う——これが泰の極みだ。"},
  "11-5": {"zh": "你到了卦的顶，泰到了头，城墙倾塌、回到壕沟，势头已经反转。泰极生否，由来已久——这时候即使有命令也行不通，死守不变只会更困境。", "en": "You're at the top of the hexagram; Tai has ended, the wall collapses back into the moat, the tide has turned. When Tai peaks, Pi comes — it's been building a while. Now even orders won't carry; holding on unchanged only deepens the straits.", "ja": "卦の頂点にいて、泰は終わり、城が崩れて壕に戻り、勢いはすでに反転した。泰が極まれば否が来る——もう久しい。今は命令があっても行われず、変えずに守ればさらに窮する。"},
  # 12 否
  "12-0": {"zh": "你在最底下，三个阴爻相互牵引上进，是否的开始，势头还不盛。同类一起进，开头还不强——守住正道、不跟他们同流，就能不被污染。", "en": "You're at the bottom; three yin lines pull each other upward — the start of Pi, its force not yet strong. Like lines advancing together, weak at first — hold to what's right and don't join them, and you stay unstained.", "ja": "一番下にいて、三つの陰が引き合って進む。否の初めで、まだ勢いが強くない。同類が進んでも初めは盛りでない——正を守って彼らと同じにならなければ、汚されずに済む。"},
  "12-1": {"zh": "你在下卦正中，上面承着九五，用柔承刚，顺着却不正。用顺从去迎合别人，是小人之道——大人物处在这种局面，宁可自己受困，也不丢掉正道。", "en": "You're at the center of the lower trigram, receiving the fifth line above — soft receiving rigid, compliant but not upright. Winning people over by compliance is the way of small men. A great person in this situation would rather be blocked themselves than lose what's right.", "ja": "下卦の中央にいて、上の九五を受け、柔で剛を承け、従顺だが正しくない。従って人に迎合するのは小人の道。大人はこの局面で、自ら否せられても正を失わない。"},
  "12-2": {"zh": "你在下卦最上面，不中不正，包容迎合到了极点，以至于自取羞辱。靠谄媚去迎合人，久了连人家也看轻你——你包藏的那点心思，终会变成你的羞耻。", "en": "You're at the top of the lower trigram — off-center and improper, your flattering compliance taken to the limit, bringing shame on yourself. Curry favor too long and even they despise you — what you harbor ends up your disgrace.", "ja": "下卦の最上部にいて、中も正も外れ、包み迎合することが極まり、自ら恥を招く。諂って人に迎合すれば、久すれば人もまた軽く見る。その包んだものは、やがて恥となる。"},
  "12-3": {"zh": "你在上卦下面，靠近九五君主，能实行自己的志向而不专断。处在闭塞之时，能有所作为的人，一定是承受君命而行——奉命去做，过错就不归自己。", "en": "You're below the upper trigram, near the fifth-line ruler, able to act on your aims without acting on your own. In a blocked time, those who can accomplish anything do so by receiving the ruler's mandate — acting on command, the fault isn't yours.", "ja": "上卦の下にいて、九五の君に近く、志を行えて専断しない。否の時、何か成せる者は必ず君の命を受ける。命を奉じて行けば、過ちは自分に帰しない。"},
  "12-4": {"zh": "你身居尊位，得中得正，能扭转闭塞的运势，心里常怀危惧。否将要转好的时候，心里更要戒惧——常拿危亡警醒自己，安稳才像系在桑树上一样牢固。", "en": "You're in the place of honor, centered and correct, able to halt the blocking tide, your heart ever watchful. When Pi is about to ease, keep fear alive — constantly warn yourself of danger, and your safety stays firm as if tied to a mulberry tree.", "ja": "尊い位にいて、中も正も得て、否の運を止め、心に常に危惧を抱く。否がやっと良くなりかける時こそ恐れる。危亡を常に心がけていれば、安さは桑に繋がるように固い。"},
  "12-5": {"zh": "你到了卦的顶，否到了头，倾覆就要转回来。否极必反，物极必反——处在这个极点，一天都不能忘了戒惧。", "en": "You're at the top of the hexagram; Pi has reached its end and is about to overturn. When Pi peaks it flips; when things are extreme they reverse — at this point, you can't forget caution for a single day.", "ja": "卦の頂点にいて、否は終わり、傾いて戻ろうとしている。否が極まれば覆り、物が極まれば必ず返る。この極にあっては、一日も恐れを忘れてはならない。"},
  # 13 同人
  "13-0": {"zh": "你在最底下，是同人的开始，走出门去寻求志同道合，心里没有偏私。出门就没有偏私——同人之道贵在公正；只偏袒自己亲近的人，同道就少了。", "en": "You're at the bottom, the start of Tongren — going out the door to seek common ground, your heart without bias. Out the door means no favoritism — the way of Tongren prizes impartiality; favor only your own and your allies dwindle.", "ja": "一番下で、同人の初め。門を出て志を同じくする者を求め、心に偏りがない。門を出れば私がない——同人の道は公を尊ぶ。親しい者に偏れば、同道は減る。"},
  "13-1": {"zh": "你在下卦正中，正应九五，但所同的只限于自己的宗族，路子窄。同人却只限自己人，是私不是公——所同的范围窄，道就走不远。", "en": "You're at the center of the lower trigram, properly matched with the fifth line, but your unity stops at your own clan — a narrow path. Uniting only with your own is private, not public; narrow unity won't carry far.", "ja": "下卦の中央にいて、九五に正しく応じるが、同じ志を結ぶのは身内まで。道が狭い。同人で身内に限るのは公ではなく私。結ぶ範囲が狭ければ、道は遠くへ行かない。"},
  "13-2": {"zh": "你在下卦最上面，过于刚强又不居中，想和同却得不到，藏着兵器伺机而动。用力气去争合同，同道反而离得更远——藏着心机等待，久了毫无结果，说明办法已经用尽。", "en": "You're at the top of the lower trigram — too rigid, off-center, wanting unity but not getting it, hiding weapons and watching for a chance. Fight for unity with force and allies drift further — lying in wait with schemes, nothing comes of it; your method is exhausted.", "ja": "下卦の最上部にいて、剛すぎて中を外れ、同じ志を結ぼうとして得られず、兵器を隠して機を伺う。力で同じにしようとすれば、結ぶ者はかえって離れる。策を隠して待っても長く成果がなく、手詰まりだ。"},
  "13-3": {"zh": "你在上卦下面，不中不正，想攻却攻不下来，反而自己停住了。理不直，力就胜不了——知道攻不动而自己罢手，这是能回到道理上来的表现。", "en": "You're below the upper trigram — off-center and improper, wanting to attack but unable, and stopping yourself instead. When the cause isn't just, force won't win — knowing you can't attack and holding back is returning to reason.", "ja": "上卦の下にいて、中も正も外れ、攻めようとして勝てず、かえって自ら止めた。理が正しくなければ力は勝てない。攻められぬと知って自ら止めるのは、理に返えることだ。"},
  "13-4": {"zh": "你身居尊位，与六二正应，被三四两爻隔开，先乖离而后相合。中正的道理，即使暂时隔开也终会相合——先用诚意相待，虽有间隔也一定能通。", "en": "You're in the place of honor, properly matched with the second line, separated by the third and fourth — first at odds, then united. The principle of centered rightness, though briefly parted, will join again — lead with sincerity and even a gap will open through.", "ja": "尊い位にいて、六二と正しく応じるが、三・四の爻に隔てられ、まず乖きて後で合う。中直の理は、しばらく隔てられても終には合う。まず誠をもって接すれば、間があっても必ず通じる。"},
  "13-5": {"zh": "你到了卦的顶，远离六二，没人可以合同，志向没实现却也不后悔。志在与人相同却没能达成，是时机没到——无所同，也就无所悔。", "en": "You're at the top of the hexagram, far from the second line, with no one to unite with — your aim unfulfilled, yet no regret. Wanting unity but not reaching it means the time hasn't come — no unity, and so no regret.", "ja": "卦の頂点にいて、六二から遠く、同じ志を結ぶ者がいない。志は達せられなかったが悔いはない。人と同じ志を結ぼうとして及ばないのは、時がまだ来ていないだけ。同じものがなく、悔いもない。"},
  # 14 大有
  "14-0": {"zh": "你在最底下，是大有的开始，还没和外物打交道，以艰难自处。刚拥有的时候，怕的是骄傲——用艰难来警醒自己，就不至于在与人交往中招害。", "en": "You're at the bottom, the start of Dayou, not yet engaged with things, dwelling in difficulty. When you first have something, the danger is pride — hold yourself with hardship and you won't meet harm in dealing with others.", "ja": "一番下で、大有の初め。まだ物と交わらず、艱難をもって自らを処する。持ち始めの患いは驕りだ。艱難で自分を戒めれば、人と交わって害を招くことはない。"},
  "14-1": {"zh": "你在下卦正中，上应六五，才力足以担重任、把所有的做大。刚健中正的才干，可以任重致远——有才干却不自用，所以前往没有祸患。", "en": "You're at the center of the lower trigram, matched with the sixth line above, with ability enough to bear burdens and grow what you have. Strong, centered talent can carry far — having ability but not using it self-importantly, you go without trouble.", "ja": "下卦の中央にいて、六五に応じ、才が重い任に足りて所有を大きくできる。剛中才は任を負って遠くへ及ぼす——才があっても自ら用いなければ、行って禍はない。"},
  "14-2": {"zh": "你在下卦最上面，处在公卿的位置，把所有的奉献给上面。有所有而不私藏，拿来奉献给主上，这是为公之道——小人却反过来只顾自己富足。", "en": "You're at the top of the lower trigram, in a public office, offering what you have to those above. Having without hoarding, giving it up to your superior — that's the public way. Small men do the opposite, enriching only themselves.", "ja": "下卦の最上部にいて、公の位にあり、持つものを上に奉じる。持っても私有せず、上に捧げるのが公の道。小人は逆に、自分だけを豊かにする。"},
  "14-3": {"zh": "你在上卦下面，靠近六五，有所有却不自盛。处在富有的世道而能自己减损盛气，就不被所有拖累——懂这个的人可以免祸。", "en": "You're below the upper trigram, near the sixth line, having much but not swelling with it. In an age of abundance, trimming your own excess means you're not burdened by it — those who know this avoid trouble.", "ja": "上卦の下にいて、六五に近く、持っていても自ら盛んにしない。富の世にあって自らその盛りを減らせば、所有に引きずられない。これを知る者は禍を免れる。"},
  "14-4": {"zh": "你身居尊位，柔和中正，五个阳爻都应你，用诚信与人交往，自然有威严。用诚实待人，不用发怒人家也敬畏——威严生于诚信，不在刑罚。", "en": "You're in the place of honor, soft and centered, with all five yang lines responding. Trusting others wins them without anger — awe arises from faith, not from punishment.", "ja": "尊い位にいて、柔らかく中を得て、五つの陽がすべて応じる。誠で人と交われば、怒らずとも人が畏れる。威厳は信から生まれ、刑にあるのではない。"},
  "14-5": {"zh": "你到了卦的顶，履行诚信、心思考顺，以刚居柔位，顺天而不自恃。履行诚信又思顺从，还尊尚贤者来辅佐自己，这是上天所助——天助的，正是自助到了极点的人。", "en": "You're at the top of the hexagram, walking in faith and thinking of compliance, rigid in a soft place — following heaven without relying on yourself. Faithful and compliant, honoring worthies to help you — this is what heaven aids. Heaven aids those who help themselves to the utmost.", "ja": "卦の頂点にいて、信を履み順を思い、剛で柔の位に居り、天に従って自らを恃まない。信を履み順を思い、さらに賢者を尊んで自らを補う——これは天が助けるところ。天が助けるのは、自ら助けを極めた者だ。"},
  # 15 谦
  "15-0": {"zh": "你在最底下，谦了又谦，以柔处下，德行越发卑下。以卑下管束自己，是君子的起点——身处低位又能甘居人下，就能渡过艰难。", "en": "You're at the bottom, humble upon humble, soft in a low place, your virtue ever more lowly. Governing yourself by lowliness is the gentleman's start — being low and willing to stay low, you can get through difficulty.", "ja": "一番下にいて、謙にまた謙、柔で下に処し、徳はますます低い。低くして自分を治めるのが君子の初め。下にいてさらに下になれるなら、難を渡れる。"},
  "15-1": {"zh": "你在下卦正中，柔顺得正，谦德显在外面，名声传开而人不怀疑。谦虚积在心里，名声自然传远——不是求人夸，是德行自然流露。", "en": "You're at the center of the lower trigram, soft and proper, humility shown outward, your name heard and trusted. Humility stored within carries your name far — not seeking praise, but virtue naturally overflowing.", "ja": "下卦の中央にいて、柔らかく正しく、謙徳が外に表れ、名声が伝わっても人は疑わない。謙が内にあれば声は自ずと遠くへ響く——人に求められたのではなく、徳が自然にほとばしるのだ。"},
  "15-2": {"zh": "你在下卦最上面，是众阴归向的人，有功而不夸耀。有功却不自居，这叫劳谦——有功劳却不占有它，所以人佩服，而且能有好结局。", "en": "You're at the top of the lower trigram, the one the yin lines turn to, with merit but no boasting. Having merit yet not claiming it — that's laboring humility. Having the labor but not owning the merit, people admire you and you keep a good end.", "ja": "下卦の最上部にいて、多くの陰が帰る者となり、功があっても誇らない。功があって自ら居ない——これを労謙という。労があっても功を自分のものにしないので、人は服し、良い終わりを得る。"},
  "15-3": {"zh": "你在上卦下面，柔顺得正，上承六五而能发挥自己的谦。谦道贵在能施展开，不只是自己守着——用谦去对待下面的人，就无往而不顺。", "en": "You're below the upper trigram, soft and proper, receiving the sixth line above and able to put your humility to work. The way of humility thrives on being expressed, not just kept — meet those below with humility and nowhere will you not be smooth.", "ja": "上卦の下にいて、柔らかく正しく、六五を受けて謙を発揮できる。謙の道は広げられることが肝心で、自分で守るだけではない。謙で下の人に接すれば、どこへ行っても順調だ。"},
  "15-4": {"zh": "你身居尊位，柔和中正又谦逊，对不服的人就用威严来辅助。以谦待人但不废威严——德行有余而还有人不服，就不能不加以讨伐。", "en": "You're in the place of honor, soft, centered and humble, backing it with severity for those who won't submit. Humility toward people without discarding dignity — when virtue is more than enough and some still won't submit, you must correct them.", "ja": "尊い位にいて、柔らかく中を得て謙遜だが、服さない者には威厳をもって補う。謙で人に接しても威を捨てない。徳が十分あるのにまだ服しない者がいれば、征さずにはいられない。"},
  "15-5": {"zh": "你到了卦的顶，谦到了极处，名声更加远播，可以行你的征伐。谦到极处，人信你信得深，所以能驱使众人——用兵，不过是端正自己私邑里不服的人罢了。", "en": "You're at the top of the hexagram, humility at its peak, your name carried even further, able to carry out your correction. At the depth of humility, people trust you deeply, so you can move the crowd — using force only sets right the unruly in your own domain.", "ja": "卦の頂点にいて、謙が極まり、名声はさらに遠くへ伝わり、征を行うことができる。謙の極は人の信が深く、それで衆を使える。兵を用いるのも、自分の私邑の従わない者を正すだけだ。"},
  # 16 豫
  "16-0": {"zh": "你在最底下，与九四相应，得意就自鸣得意，这是豫的过失。得着所乐还向人炫耀，志向就已经骄傲了——乐不可极，极了就转悲。", "en": "You're at the bottom, matched with the fourth line, and when you get your way you crow about it — Yu's failing. Getting what delights you and showing off means your aim has grown proud. Pleasure can't be maxed out; at the max it turns to sorrow.", "ja": "一番下にいて、九四に応じ、志を得て自ら誇る。豫の失いどころだ。喜びを得て人に鳴り知らせれば、志はすでに驕っている。楽しみは極めてはならず、極まれば悲しみに転じる。"},
  "16-1": {"zh": "你在下卦正中，柔顺得正而安静，不被豫乐淹没，操守像石头一样。处安乐而不沉溺，看出苗头就行动，不等到一天过完——静而有守，这就是耿介。", "en": "You're at the center of the lower trigram, soft, proper and still, not drowned in pleasure, your integrity firm as stone. In ease you don't sink; seeing the sign you act without waiting out the day — still and steadfast, that's the quality of the upright.", "ja": "下卦の中央にいて、柔らかく正しく静かで、豫の楽しみに溺れず、操守は石のよう。安楽にあっても沈まず、兆しを見れば一日を待たず動く。静かに守る——これが耿介というものだ。"},
  "16-2": {"zh": "你在下卦最上面，不中不正，抬头望着九四去求安逸。依附别人来取乐，既丢了操守，又不早作决断，所以越拖越悔。", "en": "You're at the top of the lower trigram — off-center and improper, looking up to the fourth line for ease. Leaning on others for pleasure, you lose your principles and fail to decide early, so regret grows the longer you wait.", "ja": "下卦の最上部にいて、中も正も外れ、九四を見上げて楽を求める。人に頼って楽しむのは、操守を失い、早く決めないので、遅れるほど悔いが増す。"},
  "16-3": {"zh": "你在上卦下面，是豫卦的主爻，众阴靠你得到安乐。被人依赖而安稳，就该开诚布公、不生疑心——一疑众人就离心，一诚众人就聚合。", "en": "You're below the upper trigram, the main line of Yu, the yin lines relying on you for ease. When others depend on you for peace, open your heart and don't doubt — doubt scatters them; sincerity gathers them like a hairpin.", "ja": "上卦の下にいて、豫の主爻となり、多くの陰があなたによって安楽を得る。人に頼られて安んじるなら、誠を開いて疑わないこと。疑えば衆は離れ、誠ならば簪のように集まる。"},
  "16-4": {"zh": "你身居尊位，柔和中正却乘着九四的刚，得到辅佐却不能自己作乐。得人辅佐而不能自专，像有病的人靠药才活着——之所以不死，是因为还有人扶着。", "en": "You're in the place of honor, soft and centered but riding the rigidity of the fourth line — you gain a helper but can't indulge yourself. Aided but not free to act alone, like a sick person kept alive by medicine — you survive because someone supports you.", "ja": "尊い位にいて、柔らかく中を得るが、九四の剛に乗り、補佐を得ても自ら楽しめない。人の助けを得て自専できぬのは、病んだ者が薬で生きるようなもの。死なないのは、まだ人が支えているからだ。"},
  "16-5": {"zh": "你到了卦的顶，豫到了头，沉溺已极，能改变就可以免祸。沉溺享乐到了极点还不知回头，路就快走死了——能改，过失还能补。", "en": "You're at the top of the hexagram; Yu has ended and indulgence is at its peak, but changing can save you. Drowning in pleasure to the limit without turning back, your road is nearly closed — if you change, the fault can still be mended.", "ja": "卦の頂点にいて、豫は終わり、耽りが極まった。変われれば禍を免れる。楽しみに溺れて極めてまだ返らないなら、道はもう尽きかけている。変えれば、過ちはまだ補える。"},
  # 17 随
  "17-0": {"zh": "你在最底下，是随的开始，守住常道不偏移，出门与人交往就没有私系。随人而不失正，虽有所变却能守本——出门去交，功效就及于外。", "en": "You're at the bottom, the start of Sui — keeping the constant path without swerving; going out to meet others, you have no private ties. Following others without losing what's right: though changed, you keep the root. Go out and engage, and your effect reaches outward.", "ja": "一番下にいて、随の初め。常道を守って偏らず、門を出て人と交われば私的な執わりがない。人に従っても正を失わず、変わりつつ本を守る。門を出て交われば、その働きは外に及ぶ。"},
  "17-1": {"zh": "你在下卦正中，近处系着初九，却远处失了九五。所系的是小的，所失的却是大的——随之道在于选对跟从的对象，不能两头都要。", "en": "You're at the center of the lower trigram, tied to the nearby first line but losing the distant fifth. What you hold is small; what you lose is great — following means choosing whom to follow; you can't have both.", "ja": "下卦の中央にいて、近くの初九に繋がり、遠くの九五を失う。繋いだのは小さく、失ったのは大きい。随う道は、従う相手を選ぶことにあり、両方は選べない。"},
  "17-2": {"zh": "你在下卦最上面，向上系着九四而舍了初九。跟从该跟的人，所求的就得到——随有所得却不失操守，这是会选择的。", "en": "You're at the top of the lower trigram, attached upward to the fourth line, leaving the first behind. Following whom you should follow, you get what you seek — gaining without losing your integrity: that's knowing how to choose.", "ja": "下卦の最上部にいて、上の九四に繋がり、初九を捨てた。従うべき者に従えば、求めるものが得られる。随って得ても操守を失わない——これが選べる者だ。"},
  "17-3": {"zh": "你在上卦下面，靠近九五，被众人随从而有所获。被人追随而有所得，势头逼近上面——只有存诚守道来表明自己，过错才可免。", "en": "You're below the upper trigram, near the fifth line, followed by the crowd and gaining from it. Followed and gaining, your pressure nears the one above — only by keeping faith and holding the path visibly can fault be avoided.", "ja": "上卦の下にいて、九五に近く、衆に随われて得るところがある。人に随われて得るのは、勢いが上に迫ることだ。誠を保ち道を守って自分を明らかにすれば、過ちを免れられる。"},
  "17-4": {"zh": "你身居尊位，得中得正，用诚信随顺天下的善。随的是善不是人——你所信的是善本身；君主能信善，善人自然就来。", "en": "You're in the place of honor, centered and correct, following the goodness of the world with faith. You follow the good, not people — what you trust is goodness itself. When a ruler trusts goodness, good people come of themselves.", "ja": "尊い位にいて、中も正も得て、誠信で天下の善に従う。人ではなく善に従う——信じるのは善そのもの。君が善を信じれば、善い者は自ら来る。"},
  "17-5": {"zh": "你到了卦的顶，随到了头，随得已经牢固，乃至被拘系维系。随之极而人心固结，不是靠力气能做到的——诚足以系住人，人自然就不走。", "en": "You're at the top of the hexagram; Sui has ended, your following is firm, even to being bound and tied. At the depth of following, hearts are fixed — not something force can do. When faith is enough to bind people, they stay of themselves.", "ja": "卦の頂点にいて、随は終わり、従うことは確かに固まり、拘束されて繋がるばかり。随の極は人心が固く結ばれることで、力では及ばない。誠が人を繋ぐに足れば、人は自ら去らない。"},
}
